-- BSG CBT Portal schema. Applied to the hosted project via migration.
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
grant usage on schema private to authenticated;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text not null default '',role text not null check(role in('admin','examiner','student')),created_at timestamptz not null default now());
create table public.exams(id uuid primary key default gen_random_uuid(),title text not null,level text not null,total_marks integer not null check(total_marks>0),duration_minutes integer not null check(duration_minutes>0),starts_at timestamptz,ends_at timestamptz,instructions text not null default '',status text not null default 'draft' check(status in('draft','published','closed')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),constraint valid_exam_window check(starts_at is null or ends_at is null or ends_at>starts_at));
create table public.questions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,question_text text not null,question_type text not null check(question_type in('mcq','short','long','drawing')),marks numeric(7,2) not null check(marks>0),options jsonb,position integer not null default 1,created_at timestamptz not null default now());
create table private.question_keys(question_id uuid primary key references public.questions(id) on delete cascade,correct_answer text not null,accepted_answers jsonb not null default '[]'::jsonb);
create table public.exam_assignments(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,assigned_at timestamptz not null default now(),unique(exam_id,student_id));
create table public.submissions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id),student_id uuid not null references public.profiles(id),status text not null default 'submitted' check(status in('submitted','reviewed','published')),started_at timestamptz not null default now(),submitted_at timestamptz not null default now(),published_at timestamptz,marks_awarded numeric(7,2),unique(exam_id,student_id));
create table public.answers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions(id) on delete cascade,question_id uuid not null references public.questions(id),answer_text text not null default '',auto_marks numeric(7,2) not null default 0,marks_awarded numeric(7,2),examiner_note text,unique(submission_id,question_id));
create table public.exam_sessions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,started_at timestamptz not null default now(),unique(exam_id,student_id));
-- See hosted migration cbt_core_schema_and_secure_exam_submission and server_enforced_exam_sessions_and_duration for functions, policies, grants and indexes.
